export default async function ingest({ events }, ctx) {
  let s = (await ctx.state.get("drive-transcriptions")) || {
    queue: [],
    seen: [],
    phase: "item",
    pending: null,
  };
  for (const e of events) {
    if (!e.fileId || !e.name) throw Error("Drive event missing file ID or name");
    if (!s.seen.includes(e.fileId) && !s.queue.some((x) => x.fileId === e.fileId)) s.queue.push(e);
  }
  await ctx.state.set("drive-transcriptions", s);
  return { ok: true };
}

