import { createHash } from "node:crypto";
export default async function next(
  { bucket, region, relayUrl, sheetId, range, acknowledge, resolution },
  ctx,
) {
  let s = await ctx.state.get("drive-transcriptions");
  if (!s) throw Error("Missing queue");
  if (
    !bucket ||
    bucket.includes("YOUR_") ||
    !region ||
    !sheetId ||
    sheetId.includes("YOUR_") ||
    !range ||
    !/^https:\/\//.test(relayUrl)
  )
    throw Error("Configure bucket, region, sheet and relay URL");
  let e = s.queue[0];
  if (!e)
    return {
      phase: "done",
      bucket,
      key: ".",
      region,
      jobName: ".",
      relayUrl,
      relayBody: {},
      transcriptUrl: "https://example.test/transcript.json",
      sheetId,
      range,
      values: [],
    };
  let key = e.fileId + "/" + e.name,
    jobName =
      "s3-" +
      createHash("sha256")
        .update(JSON.stringify([bucket, key]))
        .digest("hex");
  if (s.pending) {
    if (acknowledge !== s.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending write " + s.pending);
    if (resolution === "confirmed") {
      if (s.phase === "upload") s.phase = "start";
      else if (s.phase === "start") {
        s.jobName = jobName;
        s.phase = "poll";
      } else if (s.phase === "append") {
        s.seen.push(e.fileId);
        s.queue.shift();
        s.phase = "item";
      }
    }
    s.pending = null;
    await ctx.state.set("drive-transcriptions", s);
    e = s.queue[0];
    if (!e)
      return {
        phase: "done",
        bucket,
        key: ".",
        region,
        jobName: ".",
        relayUrl,
        relayBody: {},
        transcriptUrl: "https://example.test/transcript.json",
        sheetId,
        range,
        values: [],
      };
  }
  key = e.fileId + "/" + e.name;
  jobName =
    "s3-" +
    createHash("sha256")
      .update(JSON.stringify([bucket, key]))
      .digest("hex");
  if (s.phase === "item") s.phase = "upload";
  const phase = s.phase;
  if (["upload", "start", "append"].includes(phase)) {
    s.pending = phase + ":" + (phase === "start" ? jobName : e.fileId);
    await ctx.state.set("drive-transcriptions", s);
  }
  return {
    phase,
    bucket,
    key,
    region,
    jobName,
    relayUrl,
    relayBody: { fileId: e.fileId, name: e.name, bucket, key },
    transcriptUrl: s.transcriptUrl || "https://example.test/transcript.json",
    sheetId,
    range,
    values: [[e.name, e.webViewLink || "", s.createdAt || 0, s.transcript || ""]],
  };
}

