async function result(
  { kind, statusCode, body, jobName, status, createdAt, transcriptUrl, updatedRows },
  ctx,
) {
  const s = await ctx.state.get("drive-transcriptions");
  if (!s?.queue?.length) throw Error("Missing file state");
  if (kind === "upload") {
    if (statusCode < 200 || statusCode >= 300 || body?.ok !== true)
      throw Error("S3 upload not confirmed");
    s.pending = null;
    s.phase = "start";
  } else if (kind === "start") {
    if (!jobName || !status) throw Error("Transcribe start not confirmed");
    s.pending = null;
    s.jobName = jobName;
    s.createdAt = createdAt || 0;
    s.phase = "poll";
  } else if (kind === "poll") {
    if (status === "COMPLETED") {
      if (!/^https:\/\//.test(transcriptUrl || "")) throw Error("Missing completed transcript URL");
      s.transcriptUrl = transcriptUrl;
      s.createdAt = createdAt || s.createdAt || 0;
      s.phase = "transcript";
    } else if (status === "FAILED") throw Error("Transcribe job failed");
    else if (!["QUEUED", "IN_PROGRESS"].includes(status)) throw Error("Unknown Transcribe status");
  } else if (kind === "transcript") {
    if (statusCode !== 200 || !Array.isArray(body?.results?.transcripts))
      throw Error("Transcript response missing");
    s.transcript = body.results.transcripts
      .map((x) => x.transcript)
      .filter((x) => typeof x === "string")
      .join(" ");
    s.phase = "append";
  } else if (kind === "append") {
    if (updatedRows !== 1) throw Error("Sheet append not confirmed");
    s.pending = null;
    s.seen.push(s.queue[0].fileId);
    s.queue.shift();
    s.phase = "item";
    delete s.transcript;
    delete s.transcriptUrl;
    delete s.createdAt;
    delete s.jobName;
  } else throw Error("Unknown phase");
  await ctx.state.set("drive-transcriptions", s);
  return { ok: true };
}

export default async function run(input, ctx) {
  return result({ ...input, kind: "upload" }, ctx);
}

